	if len(invs) != 1 || invs[0].Status != store.InvoicePaid || len(invs[0].Lines) != 1 || invs[0].Lines[0].Quantity != 2 || invs[0].Lines[0].UnitAmount != 0 {
		t.Fatalf("invoices = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 0 {
		t.Fatalf("charges = %+v", cs)
	}
}
